'use strict';

// MODULES //

var removeANSI = require( './remove_ansi.js' );


// MAIN //

/**
* Returns the width of a Unicode string when rendered to a terminal.
*
* @private
* @param {string} str - input string
* @returns {NonNegativeInteger} number of columns
*/
function wcswidth( str ) {
	return removeANSI( str ).length; // FIXME: implement wcswidth!
}


// EXPORTS //

module.exports = wcswidth;
